SELECT ?quarterLabel ?regionName (SUM(?pct) AS ?totalProjectedDemandChange) WHERE {
  ?entry a survey:DemandForRegion ;
    survey:hasSurveyOrigin ?origin ;
    survey:inRegion ?region ;
    survey:quarter ?q ;
    survey:totalDemandPercentageChange ?pct .
  ?origin a survey:Tier1_Survey .
  ?q survey:periodLabel ?quarterLabel .
  ?region survey:regionName ?regionName .
}
GROUP BY ?quarterLabel ?regionName
ORDER BY ?quarterLabel ?regionName

SELECT ?category
       (SUM(IF(?trend = "Increase"^^xsd:string, 1, 0)) AS ?increase)
       (SUM(IF(?trend = "Decrease"^^xsd:string, 1, 0)) AS ?decrease)
       (SUM(IF(?trend = "Stable"^^xsd:string, 1, 0)) AS ?stable)
       (COUNT(?entry) AS ?total)
WHERE {
  ?entry a survey:InventoryDevelopment_Tier1 ;
         survey:forCompany ?company ;
         survey:forComponent ?comp ;
         survey:inventoryTrend ?trend .
  BIND(
    IF(?comp = survey:Component_EV, "EV",
      IF(?comp = survey:Component_non_EV, "non EV",
        IF(?comp = survey:Component_both, "mixed", REPLACE(STRAFTER(STR(?comp), "Component_"), "_", " "))
      )
    ) AS ?category
  )
  BIND(IF(?category = "EV", 1, IF(?category = "non EV", 2, IF(?category = "mixed", 3, 4))) AS ?ord)
}
GROUP BY ?category ?ord
ORDER BY ?ord

SELECT ?quarterLabel ?regionName (SUM(?pct) AS ?totalPctChange) WHERE {
  ?d a survey:DemandForRegion ;
    survey:hasSurveyOrigin ?o ;
    survey:inRegion ?r ;
    survey:quarter ?q ;
    survey:totalDemandPercentageChange ?pct .
  ?o a survey:Tier1_Survey .
  ?r survey:regionName ?regionName .
  ?q survey:periodLabel ?quarterLabel .
}
GROUP BY ?quarterLabel ?regionName
ORDER BY DESC(?totalPctChange) ?quarterLabel ?regionName
LIMIT 1

SELECT ?surveyType ?shortageCount WHERE {
  {
    SELECT ?surveyType (COUNT(?company) AS ?shortageCount) WHERE {
      VALUES (?surveyClass ?surveyType) {
        (survey:OEM_Survey 'OEM')
        (survey:Tier1_Survey 'Tier1')
        (survey:Semiconductor_Survey 'Semiconductor')
      }
      ?company a survey:Company ;
        survey:hasSurveyOrigin ?origin ;
        survey:reportsShortage true .
      ?origin a ?surveyClass .
    }
    GROUP BY ?surveyType
  }
  {
    SELECT (MAX(?cnt) AS ?maxCount) WHERE {
      {
        SELECT ?surveyType2 (COUNT(?company2) AS ?cnt) WHERE {
          VALUES (?surveyClass2 ?surveyType2) {
            (survey:OEM_Survey 'OEM')
            (survey:Tier1_Survey 'Tier1')
            (survey:Semiconductor_Survey 'Semiconductor')
          }
          ?company2 a survey:Company ;
            survey:hasSurveyOrigin ?origin2 ;
            survey:reportsShortage true .
          ?origin2 a ?surveyClass2 .
        }
        GROUP BY ?surveyType2
      }
    }
  }
  FILTER(?shortageCount = ?maxCount)
}
ORDER BY ?surveyType
